CREATE TABLE IF NOT EXISTS certificate (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  candidate_profile_id UUID NOT NULL,
  certificate_template_id UUID NOT NULL,
  certificate_status_id UUID NOT NULL,
  serial_no STRING(40) NOT NULL,
  verification_code STRING(32) NOT NULL,
  title STRING(200) NOT NULL,
  course_id UUID,
  learning_path_id UUID,
  assessment_attempt_id UUID,
  skill_id UUID,
  score_percent DECIMAL(5,2),
  issued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  content_hash STRING(64) NOT NULL,
  candidate_certification_id UUID,
  candidate_media_file_id UUID,
  revoked_at TIMESTAMPTZ,
  certificate_revocation_reason_id UUID,
  CONSTRAINT pk_certificate PRIMARY KEY (id),
  CONSTRAINT ck_certificate_score_percent_range CHECK (score_percent IS NULL OR score_percent BETWEEN 0 AND 100),
  CONSTRAINT ck_certificate_expiry_after_issue CHECK (expires_at IS NULL OR expires_at >= issued_at),
  CONSTRAINT ck_certificate_one_source CHECK (num_nonnulls(course_id, learning_path_id, assessment_attempt_id) <= 1),
  CONSTRAINT ck_certificate_revoked_consistent CHECK ((revoked_at IS NULL) = (certificate_revocation_reason_id IS NULL)),
  CONSTRAINT fk_certificate_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_certificate_template_id FOREIGN KEY (certificate_template_id) REFERENCES certificate_template (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_certificate_status_id FOREIGN KEY (certificate_status_id) REFERENCES certificate_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_course_id FOREIGN KEY (course_id) REFERENCES course (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_learning_path_id FOREIGN KEY (learning_path_id) REFERENCES learning_path (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_assessment_attempt_id FOREIGN KEY (assessment_attempt_id) REFERENCES assessment_attempt (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_skill_id FOREIGN KEY (skill_id) REFERENCES skill (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_candidate_certification_id FOREIGN KEY (candidate_certification_id) REFERENCES candidate_certification (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_candidate_media_file_id FOREIGN KEY (candidate_media_file_id) REFERENCES candidate_media_file (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_certificate_certificate_revocation_reason_id FOREIGN KEY (certificate_revocation_reason_id) REFERENCES certificate_revocation_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_certificate_serial_no (serial_no) WHERE deleted_at IS NULL,
  UNIQUE INDEX uq_certificate_verification_code (verification_code) WHERE deleted_at IS NULL,
  INDEX idx_certificate_candidate_profile_id_issued_at (candidate_profile_id, issued_at DESC) WHERE deleted_at IS NULL,
  INDEX idx_certificate_course_id (course_id) WHERE course_id IS NOT NULL,
  INDEX idx_certificate_learning_path_id (learning_path_id) WHERE learning_path_id IS NOT NULL,
  INDEX idx_certificate_assessment_attempt_id (assessment_attempt_id) WHERE assessment_attempt_id IS NOT NULL,
  INDEX idx_certificate_issued_at (issued_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_certificate_certificate_template_id (certificate_template_id),
  INDEX idx_certificate_skill_id (skill_id),
  INDEX idx_certificate_candidate_certification_id (candidate_certification_id),
  INDEX idx_certificate_candidate_media_file_id (candidate_media_file_id)
);
