  updated_by UUID NOT NULL,
  candidate_profile_id UUID NOT NULL,
  skill_gap_item_id UUID,
  course_id UUID,
  learning_path_id UUID,
  assessment_id UUID,
  rank_no INT2 NOT NULL,
  relevance_score DECIMAL(6,4) NOT NULL,
  reason_code STRING(40) NOT NULL,
  recommendation_outcome_id UUID NOT NULL,
  shown_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  acted_at TIMESTAMPTZ,
  CONSTRAINT pk_learning_recommendation PRIMARY KEY (id),
  CONSTRAINT ck_learning_recommendation_one_target CHECK (num_nonnulls(course_id, learning_path_id, assessment_id) = 1),
  CONSTRAINT fk_learning_recommendation_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_learning_recommendation_skill_gap_item_id FOREIGN KEY (skill_gap_item_id) REFERENCES skill_gap_item (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_learning_recommendation_course_id FOREIGN KEY (course_id) REFERENCES course (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_learning_recommendation_learning_path_id FOREIGN KEY (learning_path_id) REFERENCES learning_path (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_learning_recommendation_assessment_id FOREIGN KEY (assessment_id) REFERENCES assessment (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_learning_recommendation_recommendation_outcome_id FOREIGN KEY (recommendation_outcome_id) REFERENCES recommendation_outcome (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_learning_recommendation_candidate_profile_id_shown_at (candidate_profile_id, shown_at DESC),
  INDEX idx_learning_recommendation_shown_at (shown_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_learning_recommendation_course_id_recommendation_outcome_id (course_id, recommendation_outcome_id) WHERE course_id IS NOT NULL,
  INDEX idx_learning_recommendation_learning_path_id (learning_path_id) WHERE learning_path_id IS NOT NULL,
  INDEX idx_learning_recommendation_assessment_id (assessment_id) WHERE assessment_id IS NOT NULL,
  INDEX idx_learning_recommendation_skill_gap_item_id (skill_gap_item_id) WHERE skill_gap_item_id IS NOT NULL
);
