  follow_up_actions JSONB,
  rating INT2,
  wallet_ledger_entry_id UUID,
  language_id UUID,
  CONSTRAINT pk_coaching_session PRIMARY KEY (id),
  CONSTRAINT ck_coaching_session_rating_range CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  CONSTRAINT fk_coaching_session_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_coaching_session_coach_app_user_id FOREIGN KEY (coach_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coaching_session_coaching_session_type_id FOREIGN KEY (coaching_session_type_id) REFERENCES coaching_session_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coaching_session_learning_session_status_id FOREIGN KEY (learning_session_status_id) REFERENCES learning_session_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coaching_session_session_mode_id FOREIGN KEY (session_mode_id) REFERENCES session_mode (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coaching_session_sponsor_organisation_id FOREIGN KEY (sponsor_organisation_id) REFERENCES organisation (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_coaching_session_wallet_ledger_entry_id FOREIGN KEY (wallet_ledger_entry_id) REFERENCES wallet_ledger_entry (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_coaching_session_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_coaching_session_candidate_profile_id_scheduled_at (candidate_profile_id, scheduled_at DESC) WHERE deleted_at IS NULL,
  INDEX idx_coaching_session_coach_app_user_id_scheduled_at (coach_app_user_id, scheduled_at) WHERE deleted_at IS NULL,
  INDEX idx_coaching_session_sponsor_organisation_id (sponsor_organisation_id) WHERE sponsor_organisation_id IS NOT NULL,
  INDEX idx_coaching_session_wallet_ledger_entry_id (wallet_ledger_entry_id)
);
