CREATE TABLE IF NOT EXISTS mentorship_feedback (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  mentorship_session_id UUID NOT NULL,
  author_candidate_profile_id UUID NOT NULL,
  is_from_mentor BOOL NOT NULL DEFAULT false,
  rating INT2 NOT NULL,
  comment_text STRING,
  content_review_status_id UUID NOT NULL,
  is_public BOOL NOT NULL DEFAULT false,
  language_id UUID,
  CONSTRAINT pk_mentorship_feedback PRIMARY KEY (id),
  CONSTRAINT ck_mentorship_feedback_rating_range CHECK (rating BETWEEN 1 AND 5),
  CONSTRAINT fk_mentorship_feedback_author_candidate_profile_id FOREIGN KEY (author_candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_feedback_content_review_status_id FOREIGN KEY (content_review_status_id) REFERENCES content_review_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_feedback_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_mentorship_feedback_mentorship_session_id_author_candidate_profile_id (mentorship_session_id, author_candidate_profile_id) WHERE deleted_at IS NULL,
  INDEX idx_mentorship_feedback_author_candidate_profile_id (author_candidate_profile_id) WHERE deleted_at IS NULL
);
