CREATE TABLE IF NOT EXISTS mentorship_session (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  mentorship_request_id UUID,
  mentor_profile_id UUID NOT NULL,
  mentee_candidate_profile_id UUID NOT NULL,
  learning_session_status_id UUID NOT NULL,
  session_mode_id UUID NOT NULL,
  scheduled_at TIMESTAMPTZ NOT NULL,
  duration_minutes INT2 NOT NULL DEFAULT 30,
  time_zone STRING(64) NOT NULL,
  meeting_ref STRING(500),
  started_at TIMESTAMPTZ,
  ended_at TIMESTAMPTZ,
  price_amount DECIMAL(12,2),
  currency_id UUID,
  wallet_ledger_entry_id UUID,
  mentor_private_notes STRING,
  language_id UUID,
  CONSTRAINT pk_mentorship_session PRIMARY KEY (id),
  CONSTRAINT ck_mentorship_session_price_amount_nonneg CHECK (price_amount IS NULL OR price_amount >= 0),
  CONSTRAINT ck_mentorship_session_end_after_start CHECK (ended_at IS NULL OR started_at IS NOT NULL AND ended_at >= started_at),
  CONSTRAINT ck_mentorship_session_fee_pair CHECK ((price_amount IS NULL) = (currency_id IS NULL)),
  CONSTRAINT ck_mentorship_session_duration_pos CHECK (duration_minutes > 0),
  CONSTRAINT fk_mentorship_session_mentorship_request_id FOREIGN KEY (mentorship_request_id) REFERENCES mentorship_request (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_session_mentor_profile_id FOREIGN KEY (mentor_profile_id) REFERENCES mentor_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_session_mentee_candidate_profile_id FOREIGN KEY (mentee_candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_session_learning_session_status_id FOREIGN KEY (learning_session_status_id) REFERENCES learning_session_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_session_session_mode_id FOREIGN KEY (session_mode_id) REFERENCES session_mode (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_session_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_session_wallet_ledger_entry_id FOREIGN KEY (wallet_ledger_entry_id) REFERENCES wallet_ledger_entry (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_mentorship_session_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_mentorship_session_mentor_profile_id_scheduled_at (mentor_profile_id, scheduled_at) WHERE deleted_at IS NULL,
  INDEX idx_mentorship_session_mentor_profile_id_scheduled_at (mentor_profile_id, scheduled_at) WHERE deleted_at IS NULL,
  INDEX idx_mentorship_session_mentee_candidate_profile_id_scheduled_at (mentee_candidate_profile_id, scheduled_at DESC) WHERE deleted_at IS NULL,
  INDEX idx_mentorship_session_mentorship_request_id (mentorship_request_id) WHERE mentorship_request_id IS NOT NULL,
  INDEX idx_mentorship_session_currency_id (currency_id),
  INDEX idx_mentorship_session_wallet_ledger_entry_id (wallet_ledger_entry_id)
);
