CREATE TABLE IF NOT EXISTS mock_interview (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  candidate_profile_id UUID NOT NULL,
  practice_question_set_id UUID,
  target_job_role_id UUID,
  mentor_profile_id UUID,
  mock_interview_status_id UUID NOT NULL,
  session_mode_id UUID NOT NULL,
  scheduled_at TIMESTAMPTZ,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  overall_score_percent DECIMAL(5,2),
  feedback_summary STRING,
  interview_id UUID,
  language_id UUID,
  CONSTRAINT pk_mock_interview PRIMARY KEY (id),
  CONSTRAINT ck_mock_interview_overall_score_percent_range CHECK (overall_score_percent IS NULL OR overall_score_percent BETWEEN 0 AND 100),
  CONSTRAINT ck_mock_interview_end_after_start CHECK (completed_at IS NULL OR started_at IS NOT NULL AND completed_at >= started_at),
  CONSTRAINT fk_mock_interview_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_practice_question_set_id FOREIGN KEY (practice_question_set_id) REFERENCES practice_question_set (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_target_job_role_id FOREIGN KEY (target_job_role_id) REFERENCES job_role (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_mentor_profile_id FOREIGN KEY (mentor_profile_id) REFERENCES mentor_profile (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_mock_interview_status_id FOREIGN KEY (mock_interview_status_id) REFERENCES mock_interview_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_session_mode_id FOREIGN KEY (session_mode_id) REFERENCES session_mode (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_interview_id FOREIGN KEY (interview_id) REFERENCES interview (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_mock_interview_candidate_profile_id_created_at (candidate_profile_id, created_at DESC) WHERE deleted_at IS NULL,
  INDEX idx_mock_interview_mentor_profile_id_scheduled_at (mentor_profile_id, scheduled_at) WHERE mentor_profile_id IS NOT NULL,
  INDEX idx_mock_interview_interview_id (interview_id) WHERE interview_id IS NOT NULL,
  INDEX idx_mock_interview_practice_question_set_id (practice_question_set_id),
  INDEX idx_mock_interview_target_job_role_id (target_job_role_id)
);
