CREATE TABLE IF NOT EXISTS mock_interview_answer (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  mock_interview_id UUID NOT NULL,
  quiz_question_id UUID NOT NULL,
  sequence_no INT2 NOT NULL,
  recording_candidate_media_file_id UUID,
  transcript STRING,
  answer_seconds INT4 NOT NULL DEFAULT 0,
  score_percent DECIMAL(5,2),
  evaluator_kind_id UUID,
  evaluator_feedback STRING(2000),
  language_id UUID,
  CONSTRAINT pk_mock_interview_answer PRIMARY KEY (id),
  CONSTRAINT ck_mock_interview_answer_score_percent_range CHECK (score_percent IS NULL OR score_percent BETWEEN 0 AND 100),
  CONSTRAINT uq_mock_interview_answer_mock_interview_id_sequence_no UNIQUE (mock_interview_id, sequence_no),
  CONSTRAINT fk_mock_interview_answer_mock_interview_id FOREIGN KEY (mock_interview_id) REFERENCES mock_interview (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_answer_quiz_question_id FOREIGN KEY (quiz_question_id) REFERENCES quiz_question (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_answer_recording_candidate_media_file_id FOREIGN KEY (recording_candidate_media_file_id) REFERENCES candidate_media_file (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_answer_evaluator_kind_id FOREIGN KEY (evaluator_kind_id) REFERENCES evaluator_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_mock_interview_answer_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_mock_interview_answer_quiz_question_id (quiz_question_id),
  INDEX idx_mock_interview_answer_recording_candidate_media_file_id (recording_candidate_media_file_id)
);
